import{_ as t,c as i,o as n,ae as o}from"./chunks/framework.Bw0Gm4PQ.js";const p=JSON.parse('{"title":"Extending the TikTok Enforcement Delay","description":"","frontmatter":{"title":"Extending the TikTok Enforcement Delay","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/04/extending-the-tiktok-enforcement-delay/","publishDate":"2025-04-04T08:29:34-04:00"},"headers":[],"relativePath":"executive-orders/2025-04-04-extending-the-tiktok-enforcement-delay.md","filePath":"executive-orders/2025-04-04-extending-the-tiktok-enforcement-delay.md"}'),r={name:"executive-orders/2025-04-04-extending-the-tiktok-enforcement-delay.md"};function a(l,e,s,d,c,h){return n(),i("div",null,e[0]||(e[0]=[o('<h1 id="extending-the-tiktok-enforcement-delay" tabindex="-1">Extending the TikTok Enforcement Delay <a class="header-anchor" href="#extending-the-tiktok-enforcement-delay" aria-label="Permalink to &quot;Extending the TikTok Enforcement Delay&quot;">​</a></h1><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/04/extending-the-tiktok-enforcement-delay/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/04/extending-the-tiktok-enforcement-delay/</a></p><p>Published: 2025-04-04T08:29:34-04:00</p><ul><li>The enforcement delay for the Protecting Americans from Foreign Adversary Controlled Applications Act, as stated in Executive Order 14166, is extended until June 19, 2025.</li><li>During this period: <ul><li>The Department of Justice will not enforce the Act or impose penalties for noncompliance related to foreign adversary controlled applications.</li><li>This non-enforcement extends to conduct that occurred before this order, including between January 19, 2025, and the date of this order.</li></ul></li><li>The Attorney General is tasked to: <ul><li>Issue written guidance for implementing the above provisions.</li><li>Send letters to application providers confirming no violations and no liability for actions taken during the specified period.</li></ul></li><li>The Attorney General will defend the Executive’s authority against any attempts by States or private parties to enforce the Act.</li><li>This order does not affect: <ul><li>Authorities granted to executive departments or agencies.</li><li>Functions of the Director of the Office of Management and Budget.</li></ul></li><li>The order will be implemented in accordance with applicable laws and appropriations.</li><li>It does not create enforceable rights or benefits against the United States or its entities.</li></ul>',4)]))}const u=t(r,[["render",a]]);export{p as __pageData,u as default};
